    /// <summary>Every model id that has a box set.</summary>
    public static IEnumerable<string> Ids => Data.Keys;

    /// <summary>The model's boxes in its raw glTF frame (min, max).</summary>
    public static IReadOnlyList<(Vector3 Min, Vector3 Max)> Boxes(string id) => Data[id].Boxes;

    /// <summary>What the fit measured (cells, IoU, dropped dust, walkable tops).</summary>
    public static AshfallKitFitMetrics Metrics(string id) => Data[id].Metrics;

    /// <summary>The boxes are doubtful and want a manual look (see <see cref="CleanupReason"/>).</summary>
    public static bool NeedsCleanup(string id) => Data[id].NeedsCleanup;

    public static string CleanupReason(string id) => Data[id].Reason;

    /// <summary>The collision quality gate's measure of the model's boxes (draft 6; <see cref="AshfallKitFitQuality.Passes"/>).</summary>
    public static AshfallKitFitQuality Quality(string id) => Data[id].Quality;

    /// <summary>The settings the model's boxes were fitted with (chosen by the gate).</summary>
    public static AshfallKitFitSettings Settings(string id) => Data[id].Settings;

    /// <summary>The model's stair and ramp runs found in its top heightfield (raw frame; walkable models only).</summary>
    public static IReadOnlyList<AshfallRamp> Ramps(string id) => Data[id].Ramps ?? [];
}
